/** How many claims the people have in each status, in status order. */
export function statusCounts(people: PersonWithClaims[]): { status: string; count: number }[] {
  const claims = people.flatMap((p) => p.claims);
  return STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
}

// The sheet's figures summed from the list: per grade, the people on it today (retired people left
// out), their due-totals added up (n/a skipped) and how many of them are active; per period, its due-total and its change from the period before it by start date (none for the earliest); per month any claim is dated in, the dues of
// its claims that count; per status, how many
// claims have it, and how many REVIEW claims are late in review; per reason on the sheet's void reasons, how many VOID claims were voided with it. Beside it the classic
// summary: per period, its due-total counting each claim by its status now (see classicPeriodDueTotals), and the
// sheet's due-total untrimmed: everyone's due-total added up (n/a skipped).
@Component({
  selector: 'app-summary',
  imports: [FigurePipe],
  template: `
    <section aria-label="Summary">
      <h2>Summary</h2>
            @if (columnShown('overdue-count')) {<th scope="col">Overdue</th>}@if (columnShown('overdue-total')) {<th scope="col">Overdue total</th>}
            <th scope="col">Due aged 0–30</th><th scope="col">Due aged 31–60</th><th scope="col">Due aged 61+</th>
            @if (columnShown('patrons')) {<th scope="col">Patrons</th>}@if (columnShown('backing')) {<th scope="col">Backing</th>}<th scope="col">Watched</th><th scope="col">Active</th><th scope="col">Cut total</th>
            @for (pd of periods(); track pd.id) {
              <th scope="col">Due in {{ pd.name }}</th><th scope="col">Carried into {{ pd.name }}</th>
            }
            <th scope="col"><span class="visually-hidden">Actions</span></th><th scope="col">Claims</th>
          </tr>
        </thead>
        <tbody>
          @for (p of sorted(); track p.id) {
            <tr [attr.data-testid]="'person-row-' + p.id">
              <td>
                <input
                  type="checkbox"
                  data-testid="person-select"
                  [attr.aria-label]="'Select ' + p.name"
                  [checked]="selectedPeople().has(p.id)"
                  (change)="selectPerson(p, checked($event))"
                />
              </td>
              <td data-testid="person-name">{{ p.name }} ({{ p.grade }})</td>
              @if (columnShown('aliases')) {
                <td data-testid="person-aliases">{{ (p.aliases ?? []).join(', ') }}</td>
              }
              <td data-testid="person-flag-shown">{{ p.flag ?? '' }}</td>
              <td data-testid="person-approver">{{ p.approver ?? '' }}</td>
              <td data-testid="person-clashing">{{ p.clashing ? 'yes' : 'no' }}</td>
              <td data-testid="person-origin">{{ p.origin ?? '' }}</td>
              <td data-testid="person-grade">{{ p.grade }}</td>
              @if (columnShown('terms')) {
                <td data-testid="person-terms">{{ p.terms ?? '' }}</td>
              }
              @if (columnShown('contact')) {
                <td data-testid="person-contact">{{ p.contact ?? '' }}</td>
              }
              <td data-testid="person-tags">{{ (p.tags ?? []).join(', ') }}</td>
              @if (columnShown('claimed')) {
                <td data-testid="person-claimed">{{ p.claimed | figure }}</td>
              }
              @if (columnShown('due-total')) {
                <td data-testid="person-due-total">{{ (p.dueTotal ?? 'n/a') | figure }}</td>
              }
              <td data-testid="person-settled-total">{{ p.settledTotal | figure }}</td>
              <td data-testid="person-open-total">{{ p.openTotal | figure }}</td>
              <td data-testid="person-score">{{ p.score }}</td>
              <td data-testid="person-band">{{ p.band ?? '' }}</td>
              @if (columnShown('excess')) {
                <td data-testid="person-excess">{{ p.excess | figure }}</td>
              }
              @if (columnShown('statement-count')) {
                <td data-testid="person-statement-count">{{ p.statementCount }}</td>
              }
              @if (columnShown('stated-total')) {
                <td data-testid="person-stated-total">{{ (p.statementCount === 0 ? '' : (p.statedTotal ?? 'n/a')) | figure }}</td>
              }
              @if (columnShown('statement-date')) {
                <td data-testid="person-statement-date">{{ p.statementDate ?? '' }}</td>
              }
              @if (columnShown('retired')) {
                <td data-testid="person-retired">{{ p.retired ? 'yes' : 'no' }}</td>
  }

  /** Download the person's row as it shows now, as a CSV file: one line per cell, each with the value as the row
   *  shows it, columns hidden from the table included. */
  protected exportPerson(p: Person): void {
    const sheet = this.session.sheet();
    if (!sheet) return;
    const locale = this.session.locale();
    const figure = (v: string) => String(formatFigure(v, locale));
    const cells: [string, string][] = [
      ['person-name', `${p.name} (${p.grade})`],
      ['person-grade', p.grade],
      ['person-claimed', figure(p.claimed)],
      ['person-due-total', figure(p.dueTotal ?? 'n/a')],
      ['person-statement-count', String(p.statementCount)],
      ['person-overdue-total', figure(p.overdueTotal)],
      ['person-hold', p.held ? 'yes' : 'no'],
      ['person-retired', p.retired ? 'yes' : 'no'],
      ['person-aliases', (p.aliases ?? []).join(', ')],
      ['person-score', String(p.score)],
    ];

